<?php
namespace App\Domain\Shipping\Local\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
final class LocalShippingService extends Model{public const LEVELS=['same_day','next_day','scheduled'];public const PRICING_STRATEGIES=['FLAT','BASE_PLUS_OVERAGE','DISTANCE_TIERS_OVERAGE','PACKAGE_FLAT'];protected$fillable=['tenant_id','code','name','description','origin_zone_id','destination_zone_id','service_level','base_cost','base_price','currency','max_weight','max_length','max_width','max_height','estimated_min_hours','estimated_max_hours','status','published','pricing_strategy','sort_order','sla_text','service_type','valid_from','valid_to'];protected$casts=['base_cost'=>'decimal:2','base_price'=>'decimal:2','published'=>'boolean','valid_from'=>'datetime','valid_to'=>'datetime'];public function originZone():BelongsTo{return$this->belongsTo(LocalShippingZone::class,'origin_zone_id');}public function destinationZone():BelongsTo{return$this->belongsTo(LocalShippingZone::class,'destination_zone_id');}public function pricingRules(){return$this->hasMany(LocalShippingPricingRule::class,'service_id');}public function packageRules(){return$this->hasMany(LocalShippingPackageRule::class,'service_id');}}
